async function* paginateAll(fetchPage) {
  let cursor = null;
  while (true) {
    const page = await fetchPage(cursor);
    if (page && page.items) {
      for (const item of page.items) {
        yield item;
      }
    }
    if (!page || page.nextCursor === null || page.nextCursor === undefined) {
      break;
    }
    cursor = page.nextCursor;
  }
}

