const makeCancelable = (promise) => {
  let hasCanceled = false;
  const wrappedPromise = new Promise((resolve, reject) => {
    promise.then(
      (val) => (hasCanceled ? reject({ isCanceled: true }) : resolve(val)),
      (err) => (hasCanceled ? reject({ isCanceled: true }) : reject(err))
    );
  });
  return {
    promise: wrappedPromise,
    cancel() {
      hasCanceled = true;
    }
  };
}

const withTimeout = (promise, ms, timeoutError = new Error('Timeout')) => {
  let timer;
  const timeoutPromise = new Promise((_, reject) => {
    timer = setTimeout(() => reject(timeoutError), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() => {
    clearTimeout(timer);
  });
}

cancelable-promise-abort.referenceSolutionTs:
interface CancelableResult<T> {
  promise: Promise<T>;
  cancel: () => void;
}

const makeCancelable = <T,>(promise: Promise<T>): CancelableResult<T> => {
  let hasCanceled = false;
  const wrappedPromise = new Promise<T>((resolve, reject) => {
    promise.then(
      (val) => (hasCanceled ? reject({ isCanceled: true }) : resolve(val)),
      (err) => (hasCanceled ? reject({ isCanceled: true }) : reject(err))
    );
  });
  return {
    promise: wrappedPromise,
    cancel() {
      hasCanceled = true;
    }
  };
}

const withTimeout = <T,>(promise: Promise<T>, ms: number, timeoutError: Error = new Error('Timeout')): Promise<T> => {
  let timer: any;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(timeoutError), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() => {
    clearTimeout(timer);
  });
}

