  const items1 = [1, 2, 3, 4, 5, 6, 7];
  const res1 = await fn(items1, {
    batchSize: 4,
    concurrency: 2,
    processItem: async (n) => {
      activeWorkers++;
      maxActiveObserved = Math.max(maxActiveObserved, activeWorkers);
      await new Promise((r) => setTimeout(r, 10));
