    batchSize: 10,
    concurrency: 2,
    processItem: async (x) => x,
  });

  $test.check(
    'Empty input returns zero counts and empty results array',
    res4.successfulCount === 0 &&
      res4.failureCount === 0 &&
      Array.isArray(res4.results) &&
      res4.results.length === 0,
